      hi: "\u0915\u094D\u092F\u093E \u0907\u0938 \u092A\u094D\u0932\u0947\u091F\u0932\u0947\u091F \u0930\u0940\u0921\u093F\u0902\u0917 \u0915\u0940 \u092A\u0941\u0937\u094D\u091F\u093F \u0915\u0947 \u0932\u093F\u090F \u092E\u0941\u091D\u0947 \u0926\u094B\u092C\u093E\u0930\u093E \u091C\u093E\u0902\u091A \u092F\u093E \u092A\u0947\u0930\u093F\u092B\u0947\u0930\u0932 \u092C\u094D\u0932\u0921 \u0938\u094D\u092E\u0940\u092F\u0930 \u0915\u0940 \u0906\u0935\u0936\u094D\u092F\u0915\u0924\u093E \u0939\u0948?",
