        ur: "\u0641\u0627\u0633\u0679\u0646\u06AF \u0631\u06CC\u0641\u0631\u0646\u0633 \u0631\u06CC\u0646\u062C \u0633\u06D2 \u0632\u06CC\u0627\u062F\u06C1\u06D4 \u0628\u0691\u06BE\u06D2 \u06C1\u0648\u0626\u06D2 \u0641\u0627\u0633\u0679\u0646\u06AF \u06AF\u0644\u0648\u06A9\u0648\u0632 \u06A9\u0627 \u062C\u0627\u0626\u0632\u06C1 \u0688\u0627\u06A9\u0679\u0631 HbA1c \u0627\u0648\u0631 \u0622\u067E \u06A9\u06CC \u0637\u0628\u06CC \u06C1\u0633\u0679\u0631\u06CC \u06A9\u06CC \u0631\u0648\u0634\u0646\u06CC \u0645\u06CC\u06BA \u0644\u06CC\u062A\u06D2 \u06C1\u06CC\u06BA\u06D4"
