      ur: "\u0635\u0631\u0641 \u0679\u0648\u0679\u0644 \u06A9\u0648\u0644\u06CC\u0633\u0679\u0631\u0648\u0644 \u0645\u06A9\u0645\u0644 \u062A\u0635\u0648\u06CC\u0631 \u067E\u06CC\u0634 \u0646\u06C1\u06CC\u06BA \u06A9\u0631\u062A\u0627 \u0628\u0644\u06A9\u06C1 LDL \u0627\u0648\u0631 HDL \u06A9\u06D2 \u062F\u0631\u0645\u06CC\u0627\u0646 \u062A\u0648\u0627\u0632\u0646 \u0628\u06BE\u06CC \u06CC\u06A9\u0633\u0627\u06BA \u0637\u0648\u0631 \u067E\u0631 \u0627\u06C1\u0645 \u06C1\u06D2\u06D4"
