      hi: "\u0921\u0949\u0915\u094D\u091F\u0930 \u0917\u0941\u0930\u094D\u0926\u0947 \u0915\u0940 \u0915\u093E\u0930\u094D\u092F\u0915\u094D\u0937\u092E\u0924\u093E (eGFR) \u0915\u093E \u0906\u0915\u0932\u0928 \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u0940\u0930\u092E \u0915\u094D\u0930\u093F\u090F\u091F\u093F\u0928\u093F\u0928 \u0915\u094B \u0906\u092A\u0915\u0940 \u0909\u092E\u094D\u0930 \u0914\u0930 \u0932\u093F\u0902\u0917 \u0915\u0947 \u0938\u093E\u0925 \u092E\u093F\u0932\u093E\u0915\u0930 \u0926\u0947\u0916\u0924\u0947 \u0939\u0948\u0902\u0964",
