      ur: "\u0644\u06CC\u0628\u0627\u0631\u0679\u0631\u06CC\u0632 \u0648\u0679\u0627\u0645\u0646 \u0688\u06CC \u06A9\u0648 ng/mL \u06CC\u0627 nmol/L \u0645\u06CC\u06BA \u062F\u0631\u062C \u06A9\u0631 \u0633\u06A9\u062A\u06CC \u06C1\u06CC\u06BA\u06D4 \u0688\u0627\u06A9\u0679\u0631 \u06A9\u06D2 \u0645\u0634\u0648\u0631\u06D2 \u06A9\u06D2 \u0628\u063A\u06CC\u0631 \u06C1\u0627\u0626\u06CC \u0688\u0648\u0632 \u0633\u067E\u0644\u06CC\u0645\u0646\u0679\u0633 \u0634\u0631\u0648\u0639 \u0646\u06C1 \u06A9\u0631\u06CC\u06BA\u06D4"
